def scenario_catalog() -> list[dict]:
    return [{k: v for k, v in s.items() if k != "controls"} | {"suggested_control_keys": s["controls"]} for s in SCENARIOS]


def get_scenario(key: str) -> dict | None:
    return next((s for s in SCENARIOS if s["key"] == key), None)
